mapper.select:
SELECT id, evidence_id, revision_no, file_artifact_id, file_reference_id, file_version_no,
       file_scope_version, file_fact_version, file_hash,
       source_record_id, source_version, creator, create_time, tenant_id
FROM imp_delivery_evidence_revision
WHERE tenant_id = #{query.tenantId}
  AND evidence_id = #{query.evidenceId}
  AND revision_no = #{query.revisionNo}
